// Non-secret settings for ff-weekly-report (PDF task 8).
//   n8n credentials: FF Supabase (service role), FF GHL (Header Auth, agency-level key, optional),
//   FF Google Sheets (optional), FF Slack (optional).
// Monday 08:00 (after the 06:00 sync) for last week, Monday to Sunday.
// Webhook body (all optional): { client_id, week_start: "YYYY-MM-DD" (a Monday), slack: true }
//   A dashboard run never posts to Slack unless slack is true.
const SETTINGS = {
  SUPABASE_URL: 'https://SET-ME.supabase.co',
  SUPABASE_ANON_KEY: 'SET-ME',
  ALLOWED_ROLES: ['rob_admin', 'ff_staff'],
  SLACK_CHANNEL: '', // Rob's channel, e.g. '#ff-ads'; leave empty for no Slack note
  GHL_COMPANY_ID: 'SET-ME', // FF's GHL agency (company) id - same value as in ff-ghl-setup
  GHL_GOOGLE_ADS_TAG: 'from google ads', // the tag the GHL workflow adds to Google Ads leads
  SHEET_TAB: 'Weekly', // tab name in each client's Google Sheet (first row = column names)
  DASHBOARD_URL: '', // e.g. 'https://ff-ads.netlify.app' - linked at the end of the Slack note
};

const src = $input.first().json || {};
const fromWebhook = Boolean(src.headers);
const body = fromWebhook && src.body && typeof src.body === 'object' ? src.body : {};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const day = (d) => d.toISOString().slice(0, 10);

// Last full week: the Monday before this week's Monday.
const now = new Date();
const today = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
const thisMonday = new Date(today.getTime() - ((today.getUTCDay() + 6) % 7) * 86400000);
let weekStart = day(new Date(thisMonday.getTime() - 7 * 86400000));
if (typeof body.week_start === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(body.week_start)) {
  const d = new Date(`${body.week_start}T00:00:00Z`);
  if (!Number.isNaN(d.getTime()) && d.getUTCDay() === 1 && d <= today) weekStart = body.week_start;
}
const weekEnd = day(new Date(new Date(`${weekStart}T00:00:00Z`).getTime() + 6 * 86400000));

return [{
  json: {
    ...SETTINGS,
    body,
    trigger: fromWebhook ? 'manual' : 'schedule',
    only_client_id: typeof body.client_id === 'string' && uuid.test(body.client_id) ? body.client_id : null,
    send_slack: fromWebhook ? body.slack === true : true,
    week_start: weekStart,
    week_end: weekEnd,
  },
}];

// Auth check block 1/4 - read the bearer token. Never log it.
const headers = $('Webhook').first().json.headers || {};
const raw = headers.authorization || headers.Authorization || '';
const match = /^Bearer\s+(\S+)$/i.exec(String(raw).trim());
return [{ json: { token: match ? match[1] : '' } }];

// Auth check block 4/4 - decide. Output: { ok, status, error?, user? }
const cfg = $('Config').first().json;
const token = $('Auth: read token').first().json.token;
const userRes = $('Auth: verify token').first().json;
const profileRes = $('Auth: load profile').first().json;

const deny = (status, error) => [{ json: { ok: false, status, error } }];

if (!token) return deny(401, 'Missing login token.');
if (userRes.statusCode !== 200 || !userRes.body || !userRes.body.id) {
  return deny(401, 'Login token is not valid or has expired.');
}
if (profileRes.statusCode !== 200) return deny(500, 'Could not load the login profile.');

const rows = Array.isArray(profileRes.body) ? profileRes.body : [];
const profile = rows[0];
if (!profile || profile.user_id !== userRes.body.id) return deny(403, 'This login has no access.');
if (profile.disabled) return deny(403, 'This login has been turned off.');
if (!cfg.ALLOWED_ROLES.includes(profile.role)) {
  return deny(403, 'Your role does not allow this action.');
}

return [{
  json: {
    ok: true,
    status: 200,
    user: {
      user_id: profile.user_id,
      email: profile.email,
      role: profile.role,
      client_id: profile.client_id,
    },
  },
}];

// One item per active client from ff_weekly_report (most spend first).
// { none: true } when there is nothing, so the loop is skipped cleanly.
const rows = $input.all().map((i) => i.json).filter((r) => r && r.client_id && r.week_start);
if (!rows.length) return [{ json: { none: true } }];
return rows.map((r) => ({ json: r }));

// One client's week: the weekly_stats row, the tracking_health snapshot and
// the Google Sheet row. Input: the GHL count response ({ statusCode, body }),
// or the client row itself when GHL is not set up for this client.
// Counts only - GHL contacts are never read or kept (hard rule 4).
const cfg = $('Config').first().json;
const r = $('Loop over clients').first().json;
const input = $input.first().json || {};

const num = (v) => Number(v) || 0;
const money = (micros) => (num(micros) / 1e6).toFixed(2);
const count = (v) => String(Math.round(num(v) * 10) / 10);
const cur = r.currency_code || '';

// GHL leads tagged from Google Ads this week (null = not set up or not readable)
let ghlLeads = null;
const flags = [...(r.account_flags || [])];
if ('statusCode' in input) {
  // This client went through the GHL branch, so its location token ran this pass.
  const token = $('GHL: location token').first().json || {};
  const total = input.body && Number(input.body.total);
  if (!(token.statusCode >= 200 && token.statusCode < 300)) {
    flags.push(`GHL sub-account could not be opened with the FF GHL agency key (status ${token.statusCode || 'none'}) - check GHL_COMPANY_ID and the client's GHL sub-account.`);
  } else if (input.statusCode >= 200 && input.statusCode < 300 && Number.isFinite(total)) {
    ghlLeads = total;
  } else {
    flags.push(`GHL contacts could not be counted (status ${input.statusCode || 'none'}) - check the FF GHL key scopes.`);
  }
}

// Tracking
const tracking = Array.isArray(r.tracking) ? r.tracking : [];
for (const t of tracking) {
  if (t.flag_no_recent_conversions && t.primary_for_goal) {
    flags.push(`"${t.name}" has counted nothing for 14+ days while money is being spent (last: ${t.last_conversion_date || 'never'}).`);
  }
  if (t.flag_call_duration_not_90s) {
    flags.push(`"${t.name}" counts calls of ${t.phone_call_duration_seconds || 'the default'} seconds, not 90.`);
  }
}
if (r.process === 'online_cremation') {
  if (!r.has_purchase_action) flags.push('No purchase conversion action for paid arrangements.');
} else {
  if (!r.has_call_action) flags.push('No call conversion action counting calls of 90s+.');
  if (!r.has_form_action) flags.push('No preplanning form conversion action.');
}
if (num(r.ad_calls_90s_seen) > num(r.calls_90s)) {
  flags.push(`Google saw ${r.ad_calls_90s_seen} ad call(s) of 90s+ but the call conversions counted ${count(r.calls_90s)}.`);
}
if (ghlLeads !== null && ghlLeads > num(r.forms) && r.process !== 'online_cremation') {
  flags.push(`GHL received ${ghlLeads} Google Ads lead(s) but Google Ads counted ${count(r.forms)} form(s).`);
}
if (!r.last_synced_at || Date.parse(r.last_synced_at) < Date.now() - 2 * 86400000) {
  flags.push(`Google Ads data last synced ${r.last_synced_at ? r.last_synced_at.slice(0, 10) : 'never'}.`);
}

// What changed against the week before
const changes = [];
const change = (label, now, before, fmt) => {
  if (!now && !before) return;
  if (!before) { changes.push(`${label} ${fmt(now)} (none the week before).`); return; }
  const p = Math.round(((now - before) / before) * 100);
  if (Math.abs(p) < 10) return;
  changes.push(`${label} ${p > 0 ? 'up' : 'down'} ${Math.abs(p)}%: ${fmt(now)} from ${fmt(before)}.`);
};
change('Spend', num(r.cost_micros), num(r.prev_cost_micros), (v) => `${money(v)} ${cur}`.trim());
if (r.process === 'online_cremation') {
  change('Arrangements', num(r.arrangements), num(r.prev_arrangements), count);
} else {
  change('Calls 90s+', num(r.calls_90s), num(r.prev_calls_90s), count);
  change('Forms', num(r.forms), num(r.prev_forms), count);
}

// What Rob needs to decide
const decisions = [];
if (num(r.ask_rob_terms) > 0) decisions.push(`${r.ask_rob_terms} search term(s) marked ask Rob.`);
if (num(r.unsorted_terms) > 0) decisions.push(`${r.unsorted_terms} new search term(s) with spend to sort: keep, block or ask Rob.`);

const conversions = num(r.conversions);
const stats = {
  client_id: r.client_id,
  week_start: r.week_start,
  week_end: r.week_end,
  currency_code: r.currency_code || null,
  cost_micros: num(r.cost_micros),
  impressions: num(r.impressions),
  clicks: num(r.clicks),
  conversions,
  cost_per_conversion_micros: conversions > 0 ? Math.round(num(r.cost_micros) / conversions) : null,
  calls_90s: num(r.calls_90s),
  ad_calls_90s_seen: num(r.ad_calls_90s_seen),
  forms: num(r.forms),
  arrangements: num(r.arrangements),
  arrangements_value: num(r.arrangements_value),
  arrangements_started: num(r.arrangements_started),
  ghl_google_leads: ghlLeads,
  tracking_ok: flags.length === 0,
  flags,
  changes,
  decisions,
  synced_at: new Date().toISOString(),
};

const trackingRows = tracking.map((t) => ({
  customer_id: t.customer_id,
  conversion_action_id: t.conversion_action_id,
  week_start: r.week_start,
  name: t.name,
  category: t.category || null,
  type: t.type || null,
  status: t.status || null,
  primary_for_goal: t.primary_for_goal ?? null,
  phone_call_duration_seconds: t.phone_call_duration_seconds ?? null,
  last_conversion_date: t.last_conversion_date || null,
  conversions_week: num(t.conversions_week),
  spend_14d_micros: num(t.spend_14d_micros),
  flag_no_recent_conversions: Boolean(t.flag_no_recent_conversions),
  flag_call_duration_not_90s: Boolean(t.flag_call_duration_not_90s),
  synced_at: stats.synced_at,
}));

// Google Sheet row - the keys are the column names in row 1 of the tab.
const sheetRow = {
  Week: r.week_start,
  'Week end': r.week_end,
  Spend: Number(money(r.cost_micros)),
  Currency: cur,
  Clicks: num(r.clicks),
  'Calls 90s+': num(r.calls_90s),
  Forms: num(r.forms),
  Arrangements: num(r.arrangements),
  'Arrangement value': num(r.arrangements_value),
  'Cost per conversion': stats.cost_per_conversion_micros === null ? '' : Number(money(stats.cost_per_conversion_micros)),
  'GHL Google Ads leads': ghlLeads === null ? '' : ghlLeads,
  Tracking: flags.length ? 'Check' : 'OK',
  Flags: flags.join(' ').replace(/[–—]/g, '-'),
  'Needs Rob': decisions.join(' '),
};

return [{
  json: {
    client_id: r.client_id,
    week_start: r.week_start,
    google_sheet_id: r.google_sheet_id || null,
    sheet_tab: cfg.SHEET_TAB,
    stats,
    tracking_rows: trackingRows,
    sheet_row: sheetRow,
  },
}];

// Monday Slack note to Rob: per client the three key numbers, tracking, what
// changed and what he needs to decide. Calm tone, plain hyphens, no emoji,
// no search terms and no personal data (weekly_stats holds counts only).
const cfg = $('Config').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.client_id);

if (!cfg.send_slack || !cfg.SLACK_CHANNEL) {
  return [{ json: { skip: true, reason: cfg.SLACK_CHANNEL ? 'not requested' : 'no SLACK_CHANNEL' } }];
}

const num = (v) => Number(v) || 0;
const money = (micros, cur) => `${(num(micros) / 1e6).toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 0 })} ${cur || ''}`.trim();
const count = (v) => String(Math.round(num(v) * 10) / 10);
const fmtDay = (d) => new Date(`${d}T00:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });

const shown = rows
  .filter((r) => num(r.cost_micros) > 0 || (r.flags || []).length || (r.decisions || []).length)
  .sort((a, b) => num(b.cost_micros) - num(a.cost_micros));

const lines = [`FF Google Ads weekly report - ${fmtDay(cfg.week_start)} to ${fmtDay(cfg.week_end)}`];
if (!shown.length) lines.push('', 'No spend and nothing to look at this week.');

for (const r of shown.slice(0, 20)) {
  const c = r.clients || {};
  const numbers = c.process === 'online_cremation'
    ? `${count(r.arrangements)} paid arrangement(s) (${money(num(r.arrangements_value) * 1e6, r.currency_code)}), ${count(r.arrangements_started)} started`
    : `${count(r.calls_90s)} call(s) 90s+, ${count(r.forms)} form(s)`;
  lines.push('', `${c.name || 'Client'}: spent ${money(r.cost_micros, r.currency_code)}, ${numbers}. Tracking ${r.tracking_ok ? 'OK' : 'needs a look'}.`);
  for (const x of (r.changes || []).slice(0, 3)) lines.push(`- ${x}`);
  for (const x of (r.flags || []).slice(0, 4)) lines.push(`- Check: ${x}`);
  for (const x of r.decisions || []) lines.push(`- For you: ${x}`);
}
if (shown.length > 20) lines.push('', `And ${shown.length - 20} more client(s) on the dashboard.`);
if (cfg.DASHBOARD_URL) lines.push('', `Dashboard: ${cfg.DASHBOARD_URL}`);

const text = lines.join('\n').replace(/[–—]/g, '-');
return [{ json: { skip: false, text } }];
